import {useEffect,useRef,useState} from 'react';
import {useQuery,useMutation} from '@tanstack/react-query';
import {load,save} from '../api/workspace';
import {queryKey} from '../model/workspace';
import type {Scope,Values} from '../model/workspace';
import {defaults,valid} from '../forms/editor';
export function useWorkspace(scope:Scope){
const query=useQuery({queryKey:queryKey(scope),queryFn:()=>load(scope)});
const [values,setValues]=useState<Values>(()=>defaults(undefined));
const intent=useRef<string|null>(null);
useEffect(()=>{setValues(defaults(query.data));intent.current=null;},[query.data,scope.tenantId,scope.scopeRevision]);
const command=useMutation({mutationFn:(input:{values:Values;intentId:string})=>save(scope,input.values,input.intentId)});
return {vm:query.data,values,setValues,status:query.status,receipt:command.data,
submit:()=>{if(valid(values)){intent.current??=crypto.randomUUID();command.mutate({values,intentId:intent.current});}}};
}

